pub fn race_round_verdict_words(v: Rc<RaceRoundVerdict>) -> String {
    match (*v.clone()).clone() {
    RaceRoundVerdict::RaceRoundConsistent => "consistent".to_string(),
    RaceRoundVerdict::RaceRoundBothSucceeded => "FALSIFIES: both writers succeeded".to_string(),
    RaceRoundVerdict::RaceRoundInconclusive { cause: c, .. } => v1_rt::concat("inconclusive: ".to_string(), c.clone()),
}
}

pub fn race_round_line(round: i64, observation: Rc<RaceRoundObservation>) -> String {
    {
        let observed = match (*observation.clone()).clone() {
    RaceRoundObservation::RaceRoundUnseeded { cause: c, .. } => v1_rt::concat("seed refused: ".to_string(), c.clone()),
    RaceRoundObservation::RaceRoundRaced { a, b, overlap: o, .. } => Rc::new(vec!["a=".to_string(), race_report_words(a.clone()), " b=".to_string(), race_report_words(b.clone()), " overlap=".to_string(), race_overlap_words(o.clone())]).join(&"".to_string()),
};
Rc::new(vec!["round ".to_string(), (round).to_string(), " ".to_string(), observed.clone(), " -> ".to_string(), race_round_verdict_words(race_round_verdict(observation.clone()))]).join(&"".to_string())
}
}

pub fn race_probe_verdict_line(v: Rc<RaceProbeVerdict>) -> String {
    match (*v.clone()).clone() {
    RaceProbeVerdict::RaceProbePassed { rounds: n, .. } => Rc::new(vec!["verdict=passed rounds=".to_string(), (n.clone()).to_string()]).join(&"".to_string()),
    RaceProbeVerdict::RaceProbeFalsified { rounds: n, witnesses: ws, .. } => Rc::new(vec!["verdict=falsified rounds=".to_string(), (n.clone()).to_string(), " falsifying_rounds=".to_string(), Rc::new({ let mut __result = Vec::new(); for w in ws.iter().cloned() { __result.push((w.round.clone()).to_string()); } __result }).join(&",".to_string())]).join(&"".to_string()),
    RaceProbeVerdict::RaceProbeInconclusive { rounds: n, cause: c, witnesses: ws, .. } => Rc::new(vec!["verdict=inconclusive rounds=".to_string(), (n.clone()).to_string(), " cause=".to_string(), c.clone(), " inconclusive_rounds=".to_string(), Rc::new({ let mut __result = Vec::new(); for w in ws.iter().cloned() { __result.push((w.round.clone()).to_string()); } __result }).join(&",".to_string())]).join(&"".to_string()),
}
}

pub fn race_probe_receipt(declared_rounds: i64, transport: String, observations: Rc<Vec<Rc<RaceRoundObservation>>>, cleanup: String) -> String {
    {
        let lines = Rc::new({ let mut __result = Vec::new(); for pair in Rc::new(observations.clone().iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect::<Vec<_>>()).iter().cloned() { __result.push(race_round_line(v1_rt::int_add(pair.0.clone(), 1), pair.1.clone())); } __result });
v1_rt::concat(v1_rt::concat(Rc::new(vec!["instrument=gunbc.cloudflare.r2_conditional_put_race_probe run_r2_conditional_put_race_probe".to_string(), Rc::new(vec!["declared_rounds=".to_string(), (declared_rounds.clone()).to_string(), " key=".to_string(), race_probe_key()]).join(&"".to_string()), transport.clone(), race_probe_limit_line()]), lines.clone()), Rc::new(vec![cleanup.clone(), race_probe_verdict_line(race_probe_verdict(declared_rounds.clone(), observations.clone()))])).join(&"\n".to_string())
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum RaceProbeTarget {
    RaceProbeReady {
        locator: Rc<R2ObjectLocator>,
        access_key_id: NonEmptyStr,
        token: Rc<SecretRef>,
    },
    RaceProbeUnreachable {
        cause: NonEmptyStr,
    },
}

pub fn race_probe_target() -> Rc<RaceProbeTarget> {
    match (*crate::gunbc_cloudflare_r2_origin::fleet_cloudflare_account_standing()).clone() {
    FleetCloudflareAccountStanding::CloudflareAccountUnallocated { intervention: i, .. } => Rc::new(RaceProbeTarget::RaceProbeUnreachable {
    cause: v1_rt::concat("NO CLOUDFLARE ACCOUNT ID: ".to_string(), i.instruction.clone()),
}),
    FleetCloudflareAccountStanding::CloudflareAccountAllocated { account_id, .. } => match (*crate::gunbc_cloudflare_r2_origin::fabric_workspace_standing()).clone() {
    R2OriginStanding::R2OriginUnallocated { purpose: _, .. } => Rc::new(RaceProbeTarget::RaceProbeUnreachable {
    cause: "NO BUCKET ALLOCATED FOR THE FABRIC WORKSPACE".to_string(),
}),
    R2OriginStanding::R2OriginAllocated { bucket: b, .. } => match (*b.write_credential.clone()).clone() {
    OriginCredentialStanding::OriginCredentialPinned { access_key_id: k, token_value: t, .. } => Rc::new(RaceProbeTarget::RaceProbeReady {
    locator: Rc::new(R2ObjectLocator {
    endpoint: Rc::new(R2S3Endpoint {
    account_id: account_id.clone(),
    jurisdiction: b.jurisdiction.clone(),
}),
    bucket_name: b.bucket_name.clone(),
    key: race_probe_key(),
}),
    access_key_id: k.clone(),
    token: t.clone(),
}),
    OriginCredentialStanding::OriginCredentialUnminted { mint_entry: _, .. } => Rc::new(RaceProbeTarget::RaceProbeUnreachable {
    cause: "THE WORKSPACE WRITE CREDENTIAL IS NOT MINTED".to_string(),
}),
    OriginCredentialStanding::OriginCredentialMintEntryUnbuilt { secret_id: _, .. } => Rc::new(RaceProbeTarget::RaceProbeUnreachable {
    cause: "THE WORKSPACE WRITE CREDENTIAL HAS NO MINT ENTRY".to_string(),
}),
},
},
}
}

pub fn race_body_path(dir: String, name: String) -> String {
    Rc::new(vec![dir.clone(), "/".to_string(), name.clone()]).join(&"".to_string())
}

pub async fn race_write_body(path: String, round: Nat, writer: String, filesystem: &Filesystem) -> std::result::Result<bool, std::boxed::Box<dyn std::error::Error>> {
    Ok(filesystem.write(path.clone(), Rc::new(vec!["r2 conditional put race probe round ".to_string(), (round).to_string(), " ".to_string(), writer.clone(), "\n".to_string()]).join(&"".to_string())).await?.0.clone())
}

pub async fn race_seed(locator: Rc<R2ObjectLocator>, netrc: String, body: String, shell_exec: &Shell__Exec) -> std::result::Result<Option<Rc<ObjectEntityTag>>, std::boxed::Box<dyn std::error::Error>> {
    let observed = crate::gunbc_command_runner::run_shell_command_observe_outcome(crate::extdeps_tools_curl::curl_sigv4_s3_upload_command(crate::extdeps_cloudflare_r2::r2_object_url(locator), body, netrc, r2_s3_sigv4_region(), Rc::new(ObjectPutPrecondition::PutUnconditional), S3TransferReport::ReportStatusAndEntityTag), Rc::new(CommandTransport::LocalExec), compile_error!("call to run_shell_command_observe_outcome requires resource net that the calling declaration does not establish"), shell_exec).await?;
Ok(match (*crate::gunbc_cloudflare_r2_staged_transfer::classify_s3_run(observed)).clone() {
    S3TransferAnswer::S3NotAnswered { cause: _, .. } => std::option::Option::None,
    S3TransferAnswer::S3Answered { status: s, tag: t, .. } => if crate::extdeps_ietf_http_semantics::http_status_is_success(s.clone()) {
        t.clone()
    } else {
        std::option::Option::None
    },
})
}

pub async fn race_trace_reading(path: String, filesystem: &Filesystem) -> std::result::Result<Rc<CurlTraceReading>, std::boxed::Box<dyn std::error::Error>> {
    let read = filesystem.read(path.clone()).await?;
Ok(if read.1.clone() {
        crate::extdeps_tools_curl::curl_trace_reading(read.0.clone())
    } else {
        Rc::new(CurlTraceReading::CurlTraceRefused {
    cause: v1_rt::concat("the trace could not be read back: ".to_string(), read.2.clone()),
})
    })
}

pub async fn race_round(round: Nat, locator: Rc<R2ObjectLocator>, netrc: String, dir: String, filesystem: &Filesystem, shell_exec: &Shell__Exec) -> std::result::Result<Rc<RaceRoundObservation>, std::boxed::Box<dyn std::error::Error>> {
    let seed_body = race_body_path(dir.clone(), "seed".to_string());
let trace = race_body_path(dir.clone(), "trace".to_string());
let a_body = race_body_path(dir.clone(), race_writer_a());
let b_body = race_body_path(dir.clone(), race_writer_b());
Ok(if (((race_write_body(seed_body.clone(), round.clone(), "seed".to_string(), filesystem).await? && race_write_body(a_body.clone(), round.clone(), race_writer_a(), filesystem).await?) && race_write_body(b_body.clone(), round.clone(), race_writer_b(), filesystem).await?) == false) {
        Rc::new(RaceRoundObservation::RaceRoundUnseeded {
    cause: "the round's bodies could not be written locally".to_string(),
})
    } else {
        match race_seed(locator.clone(), netrc.clone(), seed_body.clone(), shell_exec).await? {
    std::option::Option::None => Rc::new(RaceRoundObservation::RaceRoundUnseeded {
    cause: "the unconditional seed PUT did not answer 2xx with an entity tag".to_string(),
}),
    Some(tag) => {
            let url = crate::extdeps_cloudflare_r2::r2_object_url(locator.clone());
let observed = crate::gunbc_command_runner::run_shell_command_observe_outcome(crate::extdeps_tools_curl::curl_sigv4_s3_parallel_upload_command(Rc::new(vec![Rc::new(S3ParallelUpload {
    label: race_writer_a(),
    url: url.clone(),
    local_path: a_body.clone(),
    precondition: Rc::new(ObjectPutPrecondition::PutIfMatch {
    tag: tag.clone(),
}),
}), Rc::new(S3ParallelUpload {
    label: race_writer_b(),
    url: url.clone(),
    local_path: b_body.clone(),
    precondition: Rc::new(ObjectPutPrecondition::PutIfMatch {
    tag: tag.clone(),
}),
})]), netrc.clone(), r2_s3_sigv4_region(), trace.clone()), Rc::new(CommandTransport::LocalExec), compile_error!("call to run_shell_command_observe_outcome requires resource net that the calling declaration does not establish"), shell_exec).await?;
match (*observed.clone()).clone() {
    ProcessRunOutcome::ProcessNotSpawned { program: p, cause: why, .. } => Rc::new(RaceRoundObservation::RaceRoundUnseeded {
    cause: Rc::new(vec!["the round's parallel writers were never spawned: ".to_string(), p.clone(), " -- ".to_string(), why.clone()]).join(&"".to_string()),
}),
    ProcessRunOutcome::ProcessRan { observation: observed, .. } => Rc::new(RaceRoundObservation::RaceRoundRaced {
    a: crate::extdeps_tools_curl::curl_parallel_transfer_report(observed.stdout.clone(), race_writer_a()),
    b: crate::extdeps_tools_curl::curl_parallel_transfer_report(observed.stdout.clone(), race_writer_b()),
    overlap: race_overlap_of_trace(race_trace_reading(trace.clone(), filesystem).await?, race_writer_a(), race_writer_b()),
}),
}
},
}
    })
}

pub async fn race_rounds(declared: i64, locator: Rc<R2ObjectLocator>, netrc: String, dir: String, filesystem: &Filesystem, shell_exec: &Shell__Exec) -> std::result::Result<Rc<Vec<Rc<RaceRoundObservation>>>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match crate::std_checked_arithmetic::checked_int_to_nat(declared) {
    std::option::Option::None => Rc::new(vec![]),
    Some(n) => Rc::new({ let mut __result = Vec::new(); for r in crate::std_nat::nat_range_inclusive(1, n.clone()).iter().cloned() { __result.push(race_round(r.clone(), locator.clone(), netrc.clone(), dir.clone(), filesystem, shell_exec).await?); } __result }),
})
}

pub async fn race_cleanup(locator: Rc<R2ObjectLocator>, netrc: String, shell_exec: &Shell__Exec) -> std::result::Result<String, std::boxed::Box<dyn std::error::Error>> {
    let observed = crate::gunbc_command_runner::run_shell_command_observe_outcome(crate::extdeps_tools_curl::curl_sigv4_s3_delete_command(crate::extdeps_cloudflare_r2::r2_object_url(locator), netrc, r2_s3_sigv4_region()), Rc::new(CommandTransport::LocalExec), compile_error!("call to run_shell_command_observe_outcome requires resource net that the calling declaration does not establish"), shell_exec).await?;
Ok(match (*crate::gunbc_cloudflare_r2_staged_transfer::classify_s3_run(observed)).clone() {
    S3TransferAnswer::S3Answered { status: s, .. } => if crate::extdeps_ietf_http_semantics::http_status_is_success(s.clone()) {
        "cleanup=probe key deleted".to_string()
    } else {
        Rc::new(vec!["cleanup=REFUSED: the probe key delete answered ".to_string(), (s.clone()).to_string(), "; the key remains".to_string()]).join(&"".to_string())
    },
    S3TransferAnswer::S3NotAnswered { cause: c, .. } => v1_rt::concat("cleanup=UNKNOWN: the probe key delete received no answer: ".to_string(), c.clone()),
})
}

pub fn race_exit(verdict: Rc<RaceProbeVerdict>, custody_clean: bool) -> Rc<ProcessExit> {
    if (custody_clean.clone() == false) {
        crate::std_process::exit_failure("the probe's credential directory or its round directory (bodies and trace) could not be removed; material may remain and requires cleanup".to_string())
    } else {
        match (*verdict.clone()).clone() {
    RaceProbeVerdict::RaceProbePassed { rounds: _, .. } => Rc::new(ProcessExit::ExitSuccess),
    RaceProbeVerdict::RaceProbeFalsified { .. } => crate::std_process::exit_failure(v1_rt::concat("THE R2 CONDITIONAL PUT IS FALSIFIED: ".to_string(), race_probe_verdict_line(verdict.clone()))),
    RaceProbeVerdict::RaceProbeInconclusive { .. } => crate::std_process::exit_failure(v1_rt::concat("THE R2 RACE PROBE IS INCONCLUSIVE: ".to_string(), race_probe_verdict_line(verdict.clone()))),
}
    }
}

pub async fn race_run_with_netrc(locator: Rc<R2ObjectLocator>, netrc: String, workspace: String, transport: String, shell_mktemp: &Shell__Mktemp, shell_remove: &Shell__Remove, filesystem: &Filesystem, shell_exec: &Shell__Exec) -> std::result::Result<Rc<ProcessExit>, std::boxed::Box<dyn std::error::Error>> {
    let staged = shell_mktemp.dir().await?;
Ok(if (staged.1.clone() == false) {
        race_exit(Rc::new(RaceProbeVerdict::RaceProbeInconclusive {
    rounds: 0,
    cause: "no directory could be created for the round bodies".to_string(),
    witnesses: Rc::new(vec![]),
}), crate::gunbc_cloudflare_r2_s3_netrc::shred_r2_s3_netrc(workspace.clone(), shell_remove).await?)
    } else {
        {
            let observations = race_rounds(race_probe_rounds(), locator.clone(), netrc.clone(), staged.0.clone(), filesystem, shell_exec).await?;
let cleanup = race_cleanup(locator.clone(), netrc.clone(), shell_exec).await?;
let custody = crate::gunbc_cloudflare_r2_s3_netrc::shred_r2_s3_netrc(workspace.clone(), shell_remove).await?;
let bodies_removed = shell_remove.recursive_force(staged.0.clone()).await?;
let receipt = race_probe_receipt(race_probe_rounds(), transport, observations.clone(), cleanup);
let written = filesystem.write(race_probe_receipt_path(), v1_rt::concat(receipt.clone(), "\n".to_string())).await?.0.clone();
if (written.clone() == false) {
                crate::std_process::exit_failure(v1_rt::concat("THE RACE PROBE RECEIPT COULD NOT BE WRITTEN: ".to_string(), race_probe_verdict_line(race_probe_verdict(race_probe_rounds(), observations.clone()))))
            } else {
                race_exit(race_probe_verdict(race_probe_rounds(), observations.clone()), (custody.clone() && bodies_removed.clone()))
            }
}
    })
}

pub async fn race_refused_before_rounds(transport: String, filesystem: &Filesystem) -> std::result::Result<Rc<ProcessExit>, std::boxed::Box<dyn std::error::Error>> {
    let receipt = race_probe_receipt(race_probe_rounds(), transport.clone(), Rc::new(vec![]), "cleanup=no round ran, so no probe key was written".to_string());
let written = filesystem.write(race_probe_receipt_path(), v1_rt::concat(receipt.clone(), "\n".to_string())).await?.0.clone();
Ok(crate::std_process::exit_failure(Rc::new(vec![if written.clone() {
        "".to_string()
    } else {
        "THE RECEIPT COULD NOT BE WRITTEN; ".to_string()
    }, "THE R2 RACE PROBE DID NOT RUN: ".to_string(), transport.clone()]).join(&"".to_string())))
}

pub fn race_transport_line(standing: Rc<CurlVersionStanding>) -> String {
    match (*standing.clone()).clone() {
    CurlVersionStanding::CurlVersionMeetsPin { observed: v, .. } => Rc::new(vec!["transport=curl ".to_string(), crate::extdeps_version_semver::semver_version_label(v.clone()), " meets ".to_string(), curl_trace_ids_cli_tool_floor()]).join(&"".to_string()),
    CurlVersionStanding::CurlVersionBelowPin { observed: v, required: r, .. } => Rc::new(vec!["transport=REFUSED curl ".to_string(), crate::extdeps_version_semver::semver_version_label(v.clone()), " is below ".to_string(), r.clone(), " (--trace-ids)".to_string()]).join(&"".to_string()),
    CurlVersionStanding::CurlVersionUnreadable { cause: c, .. } => v1_rt::concat("transport=REFUSED the curl version could not be read: ".to_string(), c.clone()),
}
}

pub fn curl_trace_ids_cli_tool_floor() -> String {
    match curl_trace_ids_cli_tool().min_version.clone() {
    Some(c) => c.clone(),
    std::option::Option::None => "no floor".to_string(),
}
}

pub async fn run_r2_conditional_put_race_probe(shell_posix_command_v: &Shell__PosixCommandV, shell_exec: &Shell__Exec, filesystem: &Filesystem, shell_env: &Shell__Env, shell_mktemp: &Shell__Mktemp, shell_remove: &Shell__Remove, crypto_sha256_sum: &Crypto__Sha256Sum, shell_g_cloud: &Shell__GCloud, gcp_secret_manager: &Gcp__SecretManager) -> std::result::Result<Rc<ProcessExit>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*crate::gunbc_host_host_cli_dependency::observe_host_cli_dependency(curl_trace_ids_cli_tool(), shell_posix_command_v).await?).clone() {
    HostCliDependencyObservation::HostCliDependencyAbsent { absence: a, .. } => crate::std_process::exit_failure(Rc::new(vec!["THE TRANSPORT IS NOT ON THIS HOST: ".to_string(), a.tool.clone(), " (".to_string(), a.hint.clone(), ")".to_string()]).join(&"".to_string())),
    HostCliDependencyObservation::HostCliDependencyPresent => match (*crate::gunbc_command_runner::run_shell_command_observe_outcome(crate::extdeps_tools_curl::curl_version_command(), Rc::new(CommandTransport::LocalExec), compile_error!("call to run_shell_command_observe_outcome requires resource net that the calling declaration does not establish"), shell_exec).await?).clone() {
    ProcessRunOutcome::ProcessNotSpawned { program: p, cause: why, .. } => race_refused_before_rounds(Rc::new(vec!["transport=REFUSED the curl version probe was never spawned: ".to_string(), p.clone(), " -- ".to_string(), why.clone()]).join(&"".to_string()), filesystem).await?,
    ProcessRunOutcome::ProcessRan { observation: version, .. } => {
        let standing = crate::extdeps_tools_curl::curl_version_standing(curl_trace_ids_cli_tool(), version.stdout.clone());
match (*standing.clone()).clone() {
    CurlVersionStanding::CurlVersionBelowPin { .. } => race_refused_before_rounds(race_transport_line(standing.clone()), filesystem).await?,
    CurlVersionStanding::CurlVersionUnreadable { cause: _, .. } => race_refused_before_rounds(race_transport_line(standing.clone()), filesystem).await?,
    CurlVersionStanding::CurlVersionMeetsPin { observed: _, .. } => race_run_with_version(race_transport_line(standing.clone()), shell_env, filesystem, shell_mktemp, shell_remove, crypto_sha256_sum, shell_g_cloud, gcp_secret_manager, shell_exec).await?,
}
},
},
})
}

pub async fn race_run_with_version(transport: String, shell_env: &Shell__Env, filesystem: &Filesystem, shell_mktemp: &Shell__Mktemp, shell_remove: &Shell__Remove, crypto_sha256_sum: &Crypto__Sha256Sum, shell_g_cloud: &Shell__GCloud, gcp_secret_manager: &Gcp__SecretManager, shell_exec: &Shell__Exec) -> std::result::Result<Rc<ProcessExit>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*race_probe_target()).clone() {
    RaceProbeTarget::RaceProbeUnreachable { cause: c, .. } => crate::std_process::exit_failure(c.clone()),
    RaceProbeTarget::RaceProbeReady { locator, access_key_id: k, token: t, .. } => match (*crate::gunbc_auth_access_token_source::select_access_token_source(shell_env, filesystem).await?).clone() {
    AccessTokenSourceSelection::AccessTokenSourceUnavailable { cause: c, .. } => crate::std_process::exit_failure(c.clone()),
    AccessTokenSourceSelection::AccessTokenSourceSelected { source: source, .. } => match (*crate::gunbc_cloudflare_r2_s3_netrc::place_r2_s3_netrc(crate::extdeps_cloudflare_r2::r2_s3_endpoint_host(locator.endpoint.clone()), k.clone(), t.clone(), source.clone(), shell_mktemp, filesystem, shell_remove, crypto_sha256_sum, shell_g_cloud, shell_env, gcp_secret_manager).await?).clone() {
    R2S3NetrcPlacement::R2S3NetrcRefused { cause: c, .. } => crate::std_process::exit_failure(c.clone()),
    R2S3NetrcPlacement::R2S3NetrcRefusedResidueRemains { cause: c, .. } => crate::std_process::exit_failure(c.clone()),
    R2S3NetrcPlacement::R2S3NetrcPlaced { binding, workspace, .. } => race_run_with_netrc(locator.clone(), crate::gunbc_auth_netrc_binding::netrc_binding_path(binding.clone()), workspace.clone(), transport, shell_mktemp, shell_remove, filesystem, shell_exec).await?,
},
},
})
}
